import json
SCALE_PATH = os.path.join(ROOT, 'tools/tech_scale.json')
SCALE = json.load(open(SCALE_PATH, encoding='utf-8')) if os.path.exists(SCALE_PATH) else {}   # множители эффектов по id (подбирает tools/tune_tech.py)


def fnum(v):
    s = ('%.4f' % v).rstrip('0').rstrip('.')
    return s if '.' in s else s + '.0'


def build():
    lines = []
    names = ['ЭКОНОМИЧЕСКАЯ', 'СОЦИАЛЬНАЯ', 'ПОЛИТИЧЕСКАЯ', 'ПРОМЫШЛЕННАЯ', 'ВОЕННАЯ']
    for b in range(5):
        lines.append('\t# ---------------- %s ----------------' % names[b])
        for t in range(14):
            opts = T[b][t]
            for k, (name, desc, fx, extra) in enumerate(opts):
                if 'growth_bonus' in fx:      # рост ВВП от технологий: ×0,75, в промышленной ветке ещё ×0,7 (часть её эффекта идёт через прибыль, безработицу, экологию)
                    fx = dict(fx, growth_bonus=round(fx['growth_bonus'] * (0.525 if b == 3 else 0.75), 3))
                tid = BRANCH_LETTER[b] + str(t) + (('abc'[k]) if len(opts) > 1 else '')
                cost = int(round(BASE * GROW ** t * OPT_COST[k] / 5.0)) * 5
                kf = float(SCALE.get(tid, 1.0)) * float(SCALE.get('_b%d' % b, 1.0))
                fxs = ', '.join('"%s": %s' % (key, fnum(round(val * kf, 4))) for key, val in fx.items())
                ex = ''
                for key in ('rs', 'cp'):
                    if key in extra:
                        ex += ', "%s": %s' % (key, fnum(round(extra[key] * kf, 4)))
                if 'req' in extra:
                    ex += ', "req": [%s]' % ', '.join('"%s"' % r for r in extra['req'])
                lines.append('\t{"id": "%s", "b": %d, "t": %d, "yr": %d, "cost": %d, "name": "%s", "d": "%s",\n\t\t"fx": {%s}%s},'
                             % (tid, b, t, TIER_YR[t], cost, name, desc, fxs, ex))
    return '\n'.join(lines)


def main():
    s = open(PATH, encoding='utf-8').read()
    a = s.index('const TECHS := [')
    b = s.index('\n]\n', a)
    head = s[:a]
    new = 'const TECHS := [\n' + build() + s[b:]
    open(PATH, 'w', encoding='utf-8').write(head + new)
    n = sum(len(v) for br in T.values() for v in br.values())
    print('технологий:', n)


if __name__ == '__main__':
    main()
